// "sveltekit-worker" is an alias defined in wrangler.jsonc that points to the
// worker generated by adapter-cloudflare at build time. Declaring it here keeps
// TypeScript from type-checking the generated build output.
declare module 'sveltekit-worker' {
	const worker: {
		fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response>;
	};
	export default worker;
}
